import (
	"strings"
	"time"

	"github.com/hebcal/hdate"
	"github.com/hebcal/locales"

	"github.com/hebcal/hebcal-go/event"
	"github.com/hebcal/hebcal-go/molad"
	"github.com/hebcal/hebcal-go/zmanim"
)

const latestKiddushLevana = "Latest Kiddush Levana"

// KiddushLevanaEvent is the latest time to recite Kiddush Levana
// (Sanctification of the Moon), calculated as halfway between one molad and
// the next, according to the Maharil (14 days, 18 hours, 22 minutes and
// 1.666 seconds after the molad).
//
// Generated by HebrewCalendar when opts.KiddushLevanaMaharil is true and
// opts.Location is provided:
//   - When the time falls during the day (between alot hashachar 16.1° and
//     tzeit 8.5°), it is moved back to alot hashachar that morning, the end
//     of the last night on which Kiddush Levana can be said.
//   - When the time falls during Shabbat or a Yom Tov, it is moved back to
//     regular candle-lighting time before that Shabbat or Yom Tov.
//   - The time is rounded down to the minute, never up.
//
// Memo lists the unadjusted earliest (3 and 7 days after the molad) and
// latest (Maharil and 15 days after the molad) times.
type KiddushLevanaEvent struct {
	TimedEvent
	// The molad of the month this event belongs to
	Molad molad.Molad
}

// GetCategories returns ["zmanim", "kiddushLevana"].
func (ev KiddushLevanaEvent) GetCategories() []string {
	return []string{"zmanim", "kiddushLevana"}
}

// Memo returns the unadjusted earliest and latest times for Kiddush Levana,
// one per line, with labels translated to locale, e.g.
// "Earliest Kiddush Levana (3 days): Mon, Sep 14, 2026, 2:39pm".
// Earliest times are rounded up to the minute and latest times down.
func (ev KiddushLevanaEvent) Memo(locale string) string {
	tz := ev.EventTime.Location()
	times := []struct {
		label string
		t     time.Time
	}{
		{"Earliest Kiddush Levana (3 days)", ceilMinute(ev.Molad.TchilasZmanKidushLevana3Days())},
		{"Earliest Kiddush Levana (7 days)", ceilMinute(ev.Molad.TchilasZmanKidushLevana7Days())},
		{"Latest Kiddush Levana (Maharil)", ev.Molad.SofZmanKidushLevanaBetweenMoldos().Truncate(time.Minute)},
		{"Latest Kiddush Levana (15 days)", ev.Molad.SofZmanKidushLevana15Days().Truncate(time.Minute)},
	}
	lines := make([]string, len(times))
	for i, zman := range times {
		label, _ := locales.LookupTranslation(zman.label, locale)
		t := zman.t.In(tz)
		timeStr := t.Format("3:04pm")
		if ev.opts.Hour24 {
			timeStr = t.Format("15:04")
		}
		lines[i] = label + ": " + t.Format("Mon, Jan 2, 2006") + ", " + timeStr
	}
	return strings.Join(lines, "\n")
}

// ceilMinute rounds t up to the next whole minute.
func ceilMinute(t time.Time) time.Time {
	floor := t.Truncate(time.Minute)
	if floor.Equal(t) {
		return t
	}
	return floor.Add(time.Minute)
}

func isShabbatOrChag(hd hdate.HDate, il bool) bool {
	if hd.Weekday() == time.Saturday {
		return true
	}
	for _, ev := range GetHolidaysOnDate(hd, il) {
		if ev.Flags.Has(event.CHAG) {
			return true
		}
	}
	return false
}

func newKiddushLevanaEvent(hd hdate.HDate, t time.Time, m molad.Molad, opts *CalOptions) KiddushLevanaEvent {
	timedEv := NewTimedEvent(hd, latestKiddushLevana, event.KIDDUSH_LEVANA, t, 0, nil, opts)
	timedEv.Emoji = "🌔"
	return KiddushLevanaEvent{TimedEvent: timedEv, Molad: m}
}

// makeKiddushLevanaEvent makes the "Latest Kiddush Levana" event for one
// Hebrew month, or returns false if it can't be calculated (e.g. no sunrise
// or sunset). The returned event's date may be earlier than the date of the
// actual latest time, when that time falls on Shabbat or a Yom Tov.
func makeKiddushLevanaEvent(hyear int, hmonth hdate.HMonth, opts *CalOptions) (KiddushLevanaEvent, bool) {
	il := opts.IL
	// Find the civil date on which the Maharil's time falls.
	// Zmanim only computes this zman between the 11th and 16th of the month.
	for dd := 11; dd <= 16; dd++ {
		hd := hdate.New(hyear, hmonth, dd)
		z := newZmanim(hd, opts)
		if z.SofZmanKidushLevanaBetweenMoldos(time.Time{}, time.Time{}).IsZero() {
			continue
		}
		// Move a daytime time back to alot hashachar that morning.
		// Same tzeit (8.5°) as IsAssurBemlacha()
		t := z.SofZmanKidushLevanaBetweenMoldos(z.AlotHaShachar(), z.Tzeit(zmanim.Tzeit3SmallStars))
		m := molad.New(hyear, hmonth)
		// After daytime adjustment the time is at night: before alot hashachar
		// it belongs to today's Hebrew date, after tzeit to tomorrow's.
		nightOf := hd
		if t.Hour() >= 12 {
			nightOf = hd.Next()
		}
		if !isShabbatOrChag(nightOf, il) {
			return newKiddushLevanaEvent(hd, t.Truncate(time.Minute), m, opts), true
		}
		// Back up to candle-lighting time before the Shabbat or Yom Tov
		first := nightOf
		for isShabbatOrChag(first.Prev(), il) {
			first = first.Prev()
		}
		erev := first.Prev()
		erevZmanim := newZmanim(erev, opts)
		candleLighting := erevZmanim.SunsetOffset(opts.CandleLightingMins, true)
		if candleLighting.IsZero() {
			return KiddushLevanaEvent{}, false
		}
		return newKiddushLevanaEvent(erev, candleLighting, m, opts), true
	}
	return KiddushLevanaEvent{}, false
}
